  PRIMARY KEY (trip_id, id),
  FOREIGN KEY (place_id) REFERENCES places(id),
  FOREIGN KEY (stay_id) REFERENCES stays(id),
  CHECK ((lat IS NULL) = (lon IS NULL))
);

CREATE TABLE budget (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  id TEXT NOT NULL,
  category TEXT NOT NULL CHECK (category IN ('getting-there', 'local-transport', 'lodging', 'food', 'activities', 'passes', 'insurance', 'misc')),
  item TEXT NOT NULL,
  currency TEXT NOT NULL,
  per_person_amount REAL CHECK (per_person_amount >= 0),
  group_low_amount REAL NOT NULL CHECK (group_low_amount >= 0),
  group_high_amount REAL NOT NULL CHECK (group_high_amount >= 0),
  basis TEXT NOT NULL CHECK (basis IN ('fare-read', 'snapshot', 'operator', 'inference', 'gap')),
  read_date TEXT,
  booking_id TEXT,
  fare_window_id TEXT,
  src TEXT NOT NULL CHECK (json_valid(src)),
  PRIMARY KEY (trip_id, id),
  FOREIGN KEY (trip_id, booking_id) REFERENCES trip_bookings(trip_id, id),
  FOREIGN KEY (trip_id, fare_window_id) REFERENCES fare_windows(trip_id, id)
);

CREATE TABLE changelog (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  seq INTEGER NOT NULL CHECK (seq >= 1),
  at TEXT NOT NULL,
  actor_id TEXT NOT NULL,
  actor_via TEXT NOT NULL,
  op TEXT NOT NULL,
  summary TEXT NOT NULL,
  refs TEXT NOT NULL CHECK (json_valid(refs)),
  PRIMARY KEY (trip_id, seq)
);

CREATE TABLE custom_items (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  id TEXT NOT NULL,
  name TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('trail', 'viewpoint', 'waterfall', 'lake', 'mountain', 'park', 'town', 'city', 'island', 'beach', 'canyon', 'valley', 'activity', 'lodge', 'drive', 'museum', 'lighthouse', 'region', 'place', 'break', 'fuel', 'rest-area')),
  lat REAL CHECK (lat >= -90 AND lat <= 90),
  lon REAL CHECK (lon >= -180 AND lon <= 180),
  address TEXT,
  osm_id TEXT,
  notes TEXT NOT NULL,
  duration_min INTEGER CHECK (duration_min >= 0),
  open_from TEXT,
  open_to TEXT,
  proposed TEXT NOT NULL CHECK (proposed IN ('no', 'proposed', 'accepted', 'rejected')),
  catalog_id TEXT,
  PRIMARY KEY (trip_id, id),
  CHECK ((lat IS NULL) = (lon IS NULL))
);

CREATE TABLE day_tracks (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  day INTEGER NOT NULL CHECK (day >= 0),
  track TEXT NOT NULL CHECK (track IN ('A', 'B', 'C', 'P')),
  audience TEXT NOT NULL CHECK (audience IN ('adult-only', 'family', 'less-walking', 'plan-b')),
  title TEXT NOT NULL,
  notes TEXT NOT NULL,
  split INTEGER NOT NULL CHECK (split IN (0,1)),
  PRIMARY KEY (trip_id, day, track),
  FOREIGN KEY (trip_id, day) REFERENCES days(trip_id, n)
);

CREATE TABLE days (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  n INTEGER NOT NULL CHECK (n >= 0),
  title TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('travel', 'hike', 'sightseeing', 'city', 'rest', 'buffer', 'mixed')),
  base_id TEXT,
  summary TEXT NOT NULL,
  prose TEXT,
  flexible_group TEXT,
  decision_rules TEXT NOT NULL CHECK (json_valid(decision_rules)),
  plan_b_title TEXT NOT NULL,
  plan_b_text TEXT,
  sun_note TEXT,
  day_of_links TEXT NOT NULL CHECK (json_valid(day_of_links)),
  accepted_warnings TEXT NOT NULL CHECK (json_valid(accepted_warnings)),
  PRIMARY KEY (trip_id, n),
  FOREIGN KEY (trip_id, base_id) REFERENCES bases(trip_id, id)
);

CREATE TABLE documents (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  id TEXT NOT NULL,
  item TEXT NOT NULL CHECK (item IN ('passport-validity', 'visa', 'eta', 'minors-consent', 'insurance', 'idp', 'park-pass', 'vaccination', 'other')),
  applies_to TEXT NOT NULL,
  rule TEXT NOT NULL,
  deadline_offset INTEGER,
  computed_rule TEXT,
  status TEXT NOT NULL,
  src TEXT NOT NULL CHECK (json_valid(src)),
  PRIMARY KEY (trip_id, id)
);

CREATE TABLE editions (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  id TEXT NOT NULL,
  label TEXT NOT NULL,
  year INTEGER NOT NULL CHECK (year >= 2000 AND year <= 2200),
  start TEXT NOT NULL,
  "end" TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('candidate', 'chosen', 'booked', 'travelled', 'cancelled')),
  why TEXT NOT NULL,
  fare_window_id TEXT,
  conditions_trigger TEXT,
  PRIMARY KEY (trip_id, id),
  FOREIGN KEY (trip_id, fare_window_id) REFERENCES fare_windows(trip_id, id)
);

CREATE TABLE emergency (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  base_id TEXT NOT NULL,
  number TEXT NOT NULL,
  hospital_name TEXT NOT NULL,
  hospital_lat REAL CHECK (hospital_lat >= -90 AND hospital_lat <= 90),
  hospital_lon REAL CHECK (hospital_lon >= -180 AND hospital_lon <= 180),
  hospital_tel TEXT,
  rescue_tel TEXT,
  embassy TEXT,
  insurer_tel TEXT,
  roadside_tel TEXT,
  src TEXT NOT NULL CHECK (json_valid(src)),
  PRIMARY KEY (trip_id, base_id),
  FOREIGN KEY (trip_id, base_id) REFERENCES bases(trip_id, id)
);

CREATE TABLE fare_quotes (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  id TEXT NOT NULL,
  window_id TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('flight-intl', 'flight-domestic', 'lodging', 'car')),
  leg TEXT NOT NULL,
  date_from TEXT NOT NULL,
  date_to TEXT NOT NULL,
  total_amount REAL NOT NULL CHECK (total_amount >= 0),
  total_currency TEXT NOT NULL,
  provider TEXT NOT NULL,
  method TEXT NOT NULL CHECK (method IN ('playwright-tfs', 'playwright-tfs-oneway', 'playwright-booking', 'manual')),
  url TEXT,
  read_at TEXT NOT NULL,
  filters TEXT NOT NULL,
  confidence TEXT NOT NULL CHECK (confidence IN ('verified', 'stated', 'inference', 'gap', 'conflict')),
  notes TEXT NOT NULL,
  PRIMARY KEY (trip_id, id),
  FOREIGN KEY (trip_id, window_id) REFERENCES fare_windows(trip_id, id)
);

CREATE TABLE fare_windows (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  id TEXT NOT NULL,
  label TEXT NOT NULL,
  depart TEXT NOT NULL,
  "return" TEXT NOT NULL,
  nights_away INTEGER NOT NULL CHECK (nights_away >= 0),
  party TEXT NOT NULL CHECK (json_valid(party)),
  school_break INTEGER NOT NULL CHECK (school_break IN (0,1)),
  notes TEXT NOT NULL,
  PRIMARY KEY (trip_id, id)
);

CREATE TABLE fx (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  currency TEXT NOT NULL,
  rate_to_base REAL NOT NULL CHECK (rate_to_base >= 0),
  as_of TEXT NOT NULL,
  source TEXT NOT NULL CHECK (source IN ('frankfurter', 'assumption')),
  PRIMARY KEY (trip_id, currency)
);

CREATE TABLE gotchas (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  id TEXT NOT NULL,
  text TEXT NOT NULL,
  src TEXT NOT NULL CHECK (json_valid(src)),
  PRIMARY KEY (trip_id, id)
);

CREATE TABLE hazards (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  id TEXT NOT NULL,
  category TEXT NOT NULL CHECK (category IN ('wind', 'cold', 'heat', 'water', 'glacier', 'wildlife', 'terrain', 'altitude', 'crime', 'health', 'road', 'remoteness', 'other')),
  title TEXT NOT NULL,
  text TEXT NOT NULL,
  severity INTEGER NOT NULL CHECK (severity >= 1 AND severity <= 3),
  days TEXT NOT NULL CHECK (json_valid(days)),
  trail_ids TEXT NOT NULL CHECK (json_valid(trail_ids)),
  place_ids TEXT NOT NULL CHECK (json_valid(place_ids)),
  mitigation TEXT NOT NULL,
  src TEXT NOT NULL CHECK (json_valid(src)),
  PRIMARY KEY (trip_id, id)
);

CREATE TABLE items (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  id TEXT NOT NULL,
  day INTEGER NOT NULL CHECK (day >= 0),
  track TEXT CHECK (track IN ('A', 'B', 'C', 'P')),
  seq INTEGER NOT NULL CHECK (seq >= 1),
  start TEXT,
  window_start TEXT,
  window_end TEXT,
  tz TEXT,
  duration_min INTEGER NOT NULL CHECK (duration_min >= 0),
  type TEXT NOT NULL CHECK (type IN ('activity', 'trail', 'sight', 'meal', 'transfer', 'checkin', 'checkout', 'buffer', 'rest', 'flight', 'break')),
  optional INTEGER NOT NULL CHECK (optional IN (0,1)),
  pinned INTEGER NOT NULL CHECK (pinned IN (0,1)),
  title TEXT NOT NULL,
  place_id TEXT,
  trail_id TEXT,
  activity_id TEXT,
  eatery_id TEXT,
  custom_item_id TEXT,
  base_id TEXT,
  booking_id TEXT,
  lat REAL CHECK (lat >= -90 AND lat <= 90),
  lon REAL CHECK (lon >= -180 AND lon <= 180),
  address TEXT,
  leg_id TEXT,
  leg_mode TEXT CHECK (leg_mode IN ('drive', 'walk', 'bus', 'shuttle', 'train', 'ferry', 'boat', 'flight', 'taxi', 'bike', 'none')),
  leg_km REAL CHECK (leg_km >= 0),
  leg_minutes INTEGER CHECK (leg_minutes >= 0),
  leg_basis TEXT CHECK (leg_basis IN ('routed', 'timetable', 'matrix', 'estimate', 'inference')),
  leg_notes TEXT NOT NULL,
  cost_amount REAL,
  cost_currency TEXT,
  cost_per TEXT CHECK (cost_per IN ('person', 'group', 'vehicle')),
  open_from TEXT,
  open_to TEXT,
  closed_weekdays TEXT NOT NULL CHECK (json_valid(closed_weekdays)),
  needs_daylight INTEGER NOT NULL CHECK (needs_daylight IN (0,1)),
  plan_b_item_id TEXT,
  override TEXT CHECK (json_valid(override)),
  notes TEXT NOT NULL,
  links TEXT NOT NULL CHECK (json_valid(links)),
  PRIMARY KEY (trip_id, id),
  FOREIGN KEY (trip_id, day) REFERENCES days(trip_id, n),
  FOREIGN KEY (place_id) REFERENCES places(id),
  FOREIGN KEY (trail_id) REFERENCES trails(id),
  FOREIGN KEY (activity_id) REFERENCES activities(id),
  FOREIGN KEY (eatery_id) REFERENCES eateries(id),
  FOREIGN KEY (trip_id, custom_item_id) REFERENCES custom_items(trip_id, id),
  FOREIGN KEY (trip_id, base_id) REFERENCES bases(trip_id, id),
  FOREIGN KEY (trip_id, booking_id) REFERENCES trip_bookings(trip_id, id),
  FOREIGN KEY (leg_id) REFERENCES legs(id),
  FOREIGN KEY (trip_id, plan_b_item_id) REFERENCES items(trip_id, id),
  CHECK ((lat IS NULL) = (lon IS NULL))
);

CREATE TABLE knowledge (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  id TEXT NOT NULL,
  claim TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('verified', 'inference', 'gap', 'conflict')),
  src TEXT NOT NULL CHECK (json_valid(src)),
  PRIMARY KEY (trip_id, id)
);

CREATE TABLE notes (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  id TEXT NOT NULL,
  scope TEXT NOT NULL CHECK (scope IN ('trip', 'day', 'item', 'place')),
  ref TEXT,
  text TEXT NOT NULL,
  visibility TEXT NOT NULL CHECK (visibility IN ('private', 'shared')),
  links TEXT NOT NULL CHECK (json_valid(links)),
  attachments TEXT NOT NULL CHECK (json_valid(attachments)),
  author TEXT NOT NULL,
  created TEXT NOT NULL,
  updated TEXT NOT NULL,
  PRIMARY KEY (trip_id, id)
);

CREATE TABLE packing (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  id TEXT NOT NULL,
  item TEXT NOT NULL,
  reason TEXT NOT NULL CHECK (reason IN ('hut', 'van', 'glacier', 'kids', 'rain', 'cold', 'altitude', 'boat', 'city')),
  qty INTEGER NOT NULL CHECK (qty >= 1),
  PRIMARY KEY (trip_id, id)
);

CREATE TABLE profile (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  pace INTEGER NOT NULL CHECK (pace >= 1 AND pace <= 5),
  comfort TEXT NOT NULL CHECK (comfort IN ('lean', 'mid', 'comfortable', 'splurge')),
  budget_target_amount REAL,
  budget_target_currency TEXT,
  budget_tier TEXT NOT NULL CHECK (budget_tier IN ('lean', 'mid', 'comfortable', 'splurge')),
  must_do TEXT NOT NULL CHECK (json_valid(must_do)),
  avoid TEXT NOT NULL CHECK (json_valid(avoid)),
  hiking_ceiling_km REAL CHECK (hiking_ceiling_km >= 0),
  hiking_ceiling_gain_m INTEGER CHECK (hiking_ceiling_gain_m >= 0),
  max_house_grade INTEGER CHECK (max_house_grade >= 1 AND max_house_grade <= 5),
  weather_rain TEXT NOT NULL CHECK (weather_rain IN ('low', 'medium', 'high')),
  weather_wind_gust_kmh INTEGER,
  weather_cold_c INTEGER,
  weather_heat_c INTEGER,
  base_preference TEXT NOT NULL CHECK (base_preference IN ('few-long', 'balanced', 'many-short', 'campsite-only')),
  car_free INTEGER NOT NULL CHECK (car_free IN (0,1)),
  transport TEXT NOT NULL CHECK (json_valid(transport)),
  daily_max_drive_min INTEGER NOT NULL CHECK (daily_max_drive_min >= 0),
  break_every_min INTEGER NOT NULL CHECK (break_every_min >= 0),
  kids_mode TEXT NOT NULL CHECK (kids_mode IN ('none', 'young', 'mid', 'teen', 'mixed')),
  early_starts TEXT NOT NULL CHECK (early_starts IN ('never', 'sometimes', 'fine')),
  night_driving INTEGER NOT NULL CHECK (night_driving IN (0,1)),
  lanes_extra TEXT NOT NULL CHECK (json_valid(lanes_extra)),
  lanes_skip TEXT NOT NULL CHECK (json_valid(lanes_skip)),
  notes TEXT NOT NULL,
  PRIMARY KEY (trip_id)
);

CREATE TABLE questions (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  id TEXT NOT NULL,
  text TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('open', 'answered', 'dropped')),
  answer TEXT,
  asked TEXT NOT NULL,
  PRIMARY KEY (trip_id, id)
);

CREATE TABLE research_refs (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  id TEXT NOT NULL,
  path TEXT NOT NULL,
  sidecar TEXT,
  lane TEXT NOT NULL,
  title TEXT NOT NULL,
  added TEXT NOT NULL,
  sha256 TEXT NOT NULL,
  synthesised TEXT,
  PRIMARY KEY (trip_id, id)
);

CREATE TABLE routes (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  id TEXT NOT NULL,
  days TEXT NOT NULL CHECK (json_valid(days)),
  waypoints TEXT NOT NULL CHECK (json_valid(waypoints)),
  profile TEXT NOT NULL CHECK (profile IN ('car', 'camper')),
  break_every_min INTEGER NOT NULL CHECK (break_every_min >= 0),
  daily_max_drive_min INTEGER NOT NULL CHECK (daily_max_drive_min >= 0),
  corridor_km REAL NOT NULL CHECK (corridor_km >= 0),
  break_types TEXT NOT NULL CHECK (json_valid(break_types)),
  avoid TEXT NOT NULL CHECK (json_valid(avoid)),
  geometry_file TEXT,
  provider TEXT CHECK (provider IN ('ors', 'osrm', 'graphhopper', 'estimate')),
  computed TEXT,
  PRIMARY KEY (trip_id, id)
);

CREATE TABLE travellers (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  id TEXT NOT NULL,
  label TEXT NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('adult', 'child', 'infant')),
  age_years INTEGER CHECK (age_years >= 0 AND age_years <= 120),
  age_as_of TEXT,
  height_cm INTEGER,
  weight_kg INTEGER,
  fitness INTEGER CHECK (fitness >= 1 AND fitness <= 5),
  citizenship TEXT NOT NULL CHECK (json_valid(citizenship)),
  notes TEXT NOT NULL,
  PRIMARY KEY (trip_id, id)
);

CREATE TABLE trip_activities (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  activity_id TEXT NOT NULL,
  day INTEGER CHECK (day >= 0),
  verdict TEXT NOT NULL CHECK (verdict IN ('in', 'optional', 'swap', 'cut')),
  why TEXT NOT NULL,
  offer_id TEXT,
  PRIMARY KEY (trip_id, activity_id),
  FOREIGN KEY (activity_id) REFERENCES activities(id),
  FOREIGN KEY (offer_id) REFERENCES offers(id)
);

CREATE TABLE trip_bookings (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  id TEXT NOT NULL,
  offer_id TEXT,
  item TEXT,
  category TEXT CHECK (category IN ('flight-intl', 'flight-domestic', 'lodging', 'hut', 'car', 'ferry', 'tour', 'activity', 'permit', 'parking', 'timed-entry', 'restaurant', 'spa', 'pass', 'insurance', 'transport', 'other')),
  book_url TEXT,
  base_id TEXT,
  used_days TEXT NOT NULL CHECK (json_valid(used_days)),
  book_by_offset INTEGER,
  book_by_basis TEXT NOT NULL CHECK (book_by_basis IN ('computed', 'owner', 'inference')),
  deadline_date TEXT,
  edition_id TEXT,
  priority TEXT NOT NULL CHECK (priority IN ('urgent', 'must', 'should', 'optional')),
  status TEXT NOT NULL CHECK (status IN ('todo', 'held', 'booked', 'paid', 'walk-up', 'sold-out', 'cancelled', 'not-needed')),
  price_paid_amount REAL,
  price_paid_currency TEXT,
  confirmation TEXT,
  contact TEXT,
  found_by TEXT NOT NULL,
  notes TEXT NOT NULL,
  src TEXT NOT NULL CHECK (json_valid(src)),
  PRIMARY KEY (trip_id, id),
  FOREIGN KEY (offer_id) REFERENCES offers(id),
  FOREIGN KEY (trip_id, base_id) REFERENCES bases(trip_id, id),
  FOREIGN KEY (trip_id, edition_id) REFERENCES editions(trip_id, id)
);

CREATE TABLE trip_sources (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  id TEXT NOT NULL,
  url TEXT NOT NULL,
  title TEXT NOT NULL,
  publisher TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('official', 'operator', 'reseller', 'press', 'blog', 'community', 'video', 'computed')),
  checked TEXT NOT NULL,
  research_ref TEXT,
  PRIMARY KEY (trip_id, id),
  FOREIGN KEY (trip_id, research_ref) REFERENCES research_refs(trip_id, id)
);

CREATE TABLE trip_tags (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  tag_id TEXT NOT NULL,
  PRIMARY KEY (trip_id, tag_id),
  FOREIGN KEY (tag_id) REFERENCES tags(id)
);

CREATE TABLE trip_trails (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  trail_id TEXT NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('track-a', 'track-b', 'track-c', 'optional', 'listed', 'rejected')),
  alternative_of TEXT,
  turnaround_rule TEXT,
  party_note TEXT NOT NULL,
  kid_fit TEXT NOT NULL CHECK (kid_fit IN ('yes', 'strong-kid', 'no', 'unknown')),
  verdict TEXT NOT NULL,
  override TEXT CHECK (json_valid(override)),
  PRIMARY KEY (trip_id, trail_id),
  FOREIGN KEY (trail_id) REFERENCES trails(id),
  FOREIGN KEY (trip_id, alternative_of) REFERENCES trip_trails(trip_id, trail_id)
);

CREATE TABLE weather_rules (
  trip_id TEXT NOT NULL REFERENCES trips(slug),
  id TEXT NOT NULL,
  day INTEGER CHECK (day >= 0),
  metric TEXT NOT NULL CHECK (metric IN ('gust_kmh', 'wind_kmh', 'precip_mm', 'precip_prob', 'temp_max_c', 'temp_min_c', 'snowline_m', 'visibility')),
  op TEXT NOT NULL CHECK (op IN ('>', '>=', '<', '<=')),
  value REAL NOT NULL,
  at TEXT NOT NULL,
  "action" TEXT NOT NULL,
  plan_b_day INTEGER CHECK (plan_b_day >= 0),
  PRIMARY KEY (trip_id, id),
  FOREIGN KEY (trip_id, day) REFERENCES days(trip_id, n),
  FOREIGN KEY (trip_id, plan_b_day) REFERENCES days(trip_id, n)
);

CREATE INDEX idx_places_review_status ON places (review_status);
CREATE INDEX idx_places_last_verified ON places (last_verified);
CREATE INDEX idx_places_area_id ON places (area_id);
CREATE INDEX idx_activities_review_status ON activities (review_status);
CREATE INDEX idx_activities_last_verified ON activities (last_verified);
CREATE INDEX idx_activities_area_id ON activities (area_id);
CREATE INDEX idx_area_guides_review_status ON area_guides (review_status);
CREATE INDEX idx_area_guides_last_verified ON area_guides (last_verified);
CREATE INDEX idx_backlog_status ON backlog (status);
CREATE INDEX idx_backlog_area_id ON backlog (area_id);
CREATE INDEX idx_catalog_changes_entity_id ON catalog_changes (entity, id);
CREATE INDEX idx_eateries_review_status ON eateries (review_status);
CREATE INDEX idx_eateries_last_verified ON eateries (last_verified);
CREATE INDEX idx_eateries_area_id ON eateries (area_id);
CREATE INDEX idx_legs_review_status ON legs (review_status);
CREATE INDEX idx_legs_last_verified ON legs (last_verified);
CREATE INDEX idx_offer_prices_offer_id ON offer_prices (offer_id);
CREATE INDEX idx_offers_review_status ON offers (review_status);
CREATE INDEX idx_offers_last_verified ON offers (last_verified);
CREATE INDEX idx_offers_area_id ON offers (area_id);
CREATE INDEX idx_stays_review_status ON stays (review_status);
CREATE INDEX idx_stays_last_verified ON stays (last_verified);
CREATE INDEX idx_stays_area_id ON stays (area_id);
CREATE INDEX idx_trails_review_status ON trails (review_status);
CREATE INDEX idx_trails_last_verified ON trails (last_verified);
CREATE INDEX idx_trails_area_id ON trails (area_id);
CREATE INDEX idx_trips_owner_id ON trips (owner_id);
CREATE INDEX idx_trips_visibility ON trips (visibility);
CREATE INDEX idx_items_day_track_seq ON items (trip_id, day, track, seq);
